changeSet.sql:
INSERT INTO nexus.data_moves (label, template, driving_schema, driving_table, chunk_size, sleep_ms, statement_timeout_ms, verification, on_complete, changeset_id, supersedes) VALUES
    ('g-move-1', 'UPDATE nexus.chunks SET new_col = old_col WHERE new_col IS NULL; DELETE FROM nexus.chunks WHERE dead', 'nexus', 'chunks', 1000, 50, 60000, 'SELECT count(*) FROM nexus.chunks WHERE new_col IS NULL AND tenant_id = $1', 'ALTER TABLE nexus.chunks VALIDATE CONSTRAINT moved_check', 'g-move-1', NULL);
ALTER TABLE nexus.chunks ADD COLUMN new_col int;
ALTER TABLE nexus.chunks ADD CONSTRAINT chunks_new_check CHECK (new_col > 0) NOT VALID;
ALTER TABLE nexus.chunks ADD CONSTRAINT chunks_new_fk FOREIGN KEY (new_col) REFERENCES nexus.sizes (id) NOT VALID;

INSERT INTO nexus.data_moves (label, template, driving_schema, driving_table, chunk_size, sleep_ms, statement_timeout_ms, verification)
VALUES ('g-move-2', $t$UPDATE nexus.catalog_links SET a = 1; DELETE FROM nexus.catalog_links$t$, 'nexus', 'catalog_links', 10, 0, 1000, $v$SELECT 1$v$),
       ('g-move-3', $t$INSERT INTO nexus.x SELECT 1$t$, 'nexus', 'topic_assignments', 10, 0, 1000, 'SELECT 1');

SELECT 'UPDATE nexus.chunks SET x = 1; DELETE FROM nexus.chunks';
-- UPDATE nexus.chunks SET x = 1
/* a /* b */ DELETE FROM nexus.chunks; */
COMMENT ON TABLE nexus.t IS E'UPDATE it\'s; DELETE FROM x';
SELECT 1;

DO $$ BEGIN UPDATE nexus.chunks SET x = 1; DELETE FROM nexus.catalog_links; END $$;
CREATE OR REPLACE FUNCTION nexus.f() RETURNS void LANGUAGE plpgsql AS $body$ BEGIN UPDATE nexus.chunks SET x = 2; END $body$;
DO $outer$ BEGIN EXECUTE format('ALTER TABLE %I VALIDATE CONSTRAINT c', 'chunks'); END $outer$;

ALTER TABLE nexus.t ALTER COLUMN c SET DEFAULT 1;
ALTER TABLE nexus.t ADD COLUMN type text;
ALTER TABLE nexus.t ADD CONSTRAINT fk FOREIGN KEY (a) REFERENCES nexus.u (a) ON UPDATE CASCADE ON DELETE SET NULL;
CREATE TABLE nexus.t2 (id int, g int GENERATED ALWAYS AS (id + 1) STORED, CONSTRAINT c CHECK (id > 0));
CREATE TABLE nexus.t3 (id int) PARTITION BY LIST (id);
CREATE TRIGGER trg BEFORE UPDATE OR DELETE ON nexus.t FOR EACH ROW EXECUTE FUNCTION nexus.f();
GRANT UPDATE, DELETE ON nexus.t TO some_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA nexus GRANT UPDATE ON TABLES TO some_role;
CREATE POLICY p ON nexus.t FOR UPDATE USING (true);
